# %% ../../nbs/02.04_BiasingMethods.ipynb 8
def quantile(tau, dist, gpoints):
    """
    Computes the `tau`-quantile of any distribution `dist`,
    given a set of gridpoints `gpoints`.
    """
    dim = dist[..., -1].shape  # shape of the distrib except last axis
    qdist0 = np.ones(dim) * -1  
    qdist = jnp.ones(dim) * -1  # will store the quantiles for each axis
    sums = jnp.cumsum(dist, axis=-1)  # add up bins
    mask = sums < tau  # find tau such that sum >= tau
    qidx = jnp.sum(mask, axis=-1)  # indices of the tau-quantile for each axis
    for index, _ in np.ndenumerate(qdist0):
        idx = qidx[index] - 1
        qdist = qdist.at[index].set((gpoints[idx]+gpoints[idx+1])/2)  # quantile
        # is between these two points
    return qdist

# %% ../../nbs/02.04_BiasingMethods.ipynb 10
def expectile(tau, dist, gpoints):
    """
    Computes the `tau`-expectile of any distribution `dist`,
    given a set of gridpoints `gpoints`.
    """
    dim = dist.shape  # shape of dist 
    dim1 = dist[..., -1].shape  # shape of dist - last axis
    
    # Constructing the b_i matrix
    bdiffs = np.zeros(dim[:-1]+(len(gpoints), len(gpoints)))
    bdiffs = np.repeat(dist[..., np.newaxis], len(gpoints), axis=-1)
    bdiffs = jnp.rot90(bdiffs, 1, axes=(-2, -1))
    
    # Constructing the x_i and x_k matrices
    xi = jnp.zeros((len(gpoints), len(gpoints)))
    xk = jnp.zeros((len(gpoints), len(gpoints)))
    xi = xi.at[:, :].set(gpoints)
    xk = xk.at[:, :].set(gpoints)
    xk = xk.T
    
    # Computing x_i - x_k and x_k - x_i (on same matrix)
    xdiffs = jnp.zeros(dim[:-1]+(len(gpoints), len(gpoints)))
    adiffs = jnp.abs(xi - xk)
    xdiffs = xdiffs.at[..., :, :].set(adiffs)
    
    # Computing (x_i - x_k) * b_i and (x_k - x_i) * bi
    xb = xdiffs * bdiffs
    xb_num = jnp.tril(xb, 0)  # (x_k - x_i) * bi
    xb_den = jnp.triu(xb, 0)  # (x_i - x_k) * b_i
    
    # Computing sum{(x_k - x_i)*b_i}/sum{(x_i - x_k)*b_i} for all k
    candidates = jnp.sum(xb_num[..., :-1, :], axis=-1) / jnp.sum(xb_den[..., :-1, :], axis=-1)
    
    # Compute expectiles
    edist0 = np.ones(dim1) * -1
    edist = jnp.ones(dim1) * -1  # will store expectiles
    mask = candidates < tau / (1 - tau)  # find the expectile
    eidx = jnp.sum(mask, axis=-1)  # expectile indices
    for index, _ in np.ndenumerate(edist0):
        idx = eidx[index] - 1
        edist = edist.at[index].set((gpoints[idx] + gpoints[idx+1]) / 2)
    return edist

# %% ../../nbs/02.04_BiasingMethods.ipynb 12
def weights(w, dist, gpoints):
    """
    Computes a weighted estimate of any distribution `dist`,
    given a set of gridpoints `gpoints`.
    """
    new_dist = w * dist  # apply the weights
    # Normalize the new distributions
    norm = jnp.sum(new_dist, axis=-1)  
    norm = jnp.repeat(norm[..., jnp.newaxis], len(gpoints), axis=-1)
    new_dist = new_dist / norm
    return new_dist
